('p1_dif02_retest','retest','DIF-02 delayed retest','DIF-02 отложенный ретест','DIF-02 kechiktirilgan retest'),('p1_dif03_retest','retest','DIF-03 delayed retest','DIF-03 отложенный ретест','DIF-03 kechiktirilgan retest'),('p1_dif04_retest','retest','DIF-04 delayed retest','DIF-04 отложенный ретест','DIF-04 kechiktirilgan retest'),
